const items = $input.all();

function clean(value) {
  return String(value || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&#8217;/g, "'")
    .replace(/&#8220;/g, '"')
    .replace(/&#8221;/g, '"')
    .replace(/&#8230;/g, '...')
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

function getLink(j) {
  return String(j.link || j.guid || j.id || j.url || '').trim();
}

function detectSource(j) {
  const link = getLink(j).toLowerCase();

  if (link.includes('techcrunch.com')) return 'TechCrunch';
  if (link.includes('theverge.com')) return 'The Verge';
  if (link.includes('openai.com')) return 'OpenAI Blog';

  return clean(
    j.feedTitle ||
    j.source ||
    j.creator ||
    j['dc:creator'] ||
    j.author ||
    'RSS Feed'
  );
}

function getPublishedAt(j) {
  const dateRaw = j.isoDate || j.pubDate || j.date || j.published || '';

  if (!dateRaw) return '';

  const parsedDate = new Date(dateRaw);

  if (isNaN(parsedDate.getTime())) return '';

  return parsedDate.toISOString();
}

const rows = items
  .map((item) => {
    const j = item.json || {};

    const title = clean(j.title);
    const link = getLink(j);
    const source = detectSource(j);
    const published_at = getPublishedAt(j);
    const summary = clean(
      j.contentSnippet ||
      j.content ||
      j.description ||
      j.summary ||
      ''
    );

    return {
      title,
      link,
      source,
      published_at,
      summary
    };
  })
  .filter((row) => row.title && row.link);

if (!rows.length) {
  throw new Error(
    `No valid RSS articles found. Input items received: ${items.length}. First item: ` +
    JSON.stringify(items[0]?.json || {}).slice(0, 1000)
  );
}

const seen = new Set();
const deduped = [];

for (const row of rows) {
  const key = row.link.toLowerCase();

  if (!seen.has(key)) {
    seen.add(key);
    deduped.push(row);
  }
}

const grouped = {};

for (const article of deduped) {
  if (!grouped[article.source]) {
    grouped[article.source] = [];
  }

  grouped[article.source].push(article);
}

for (const source of Object.keys(grouped)) {
  grouped[source].sort((a, b) => {
    const dateA = a.published_at ? new Date(a.published_at).getTime() : 0;
    const dateB = b.published_at ? new Date(b.published_at).getTime() : 0;

    return dateB - dateA;
  });
}

const sourceOrder = ['TechCrunch', 'The Verge', 'OpenAI Blog'];
const balanced = [];

for (const source of sourceOrder) {
  const sourceArticles = grouped[source] || [];

  balanced.push(...sourceArticles.slice(0, 5));
}

for (const source of Object.keys(grouped)) {
  if (!sourceOrder.includes(source)) {
    balanced.push(...grouped[source].slice(0, 3));
  }
}

const topArticles = balanced
  .filter(Boolean)
  .slice(0, 15);

if (!topArticles.length) {
  throw new Error('No articles remained after source balancing.');
}

const sourceCounts = topArticles.reduce((acc, article) => {
  acc[article.source] = (acc[article.source] || 0) + 1;
  return acc;
}, {});

let cadence = {};
try {
  cadence = $('Apply Editorial Cadence and Safety Gate').first().json || {};
} catch {}

let recentRecords = [];
try {
  const history = $('Load Recent Publishing History').first().json || {};
  recentRecords = Array.isArray(history.records) ? history.records : [];
} catch {}

const recent_content = recentRecords.slice(0, 20).map(r => {
  const f = r.fields || {};
  return {
    topic: String(f.Topic || '').trim(),
    source_url: String(f.Source_URL || '').trim(),
    hook: String(f.Hook || '').trim(),
    cta: String(f.CTA || '').trim(),
    content_pillar: String(f.Content_Pillar || '').trim(),
    post_variant: String(f.Post_Variant || '').trim(),
    status: String(f.Status || '').trim(),
    created_at: String(f.Created_At || r.createdTime || '').trim()
  };
}).filter(r => r.topic || r.source_url || r.hook);

return [
  {
    json: {
      run_id: `community-linkedin-${new Date().toISOString()}`,
      created_at: new Date().toISOString(),
      ...cadence,
      total_input_items: items.length,
      valid_article_count: rows.length,
      article_count: topArticles.length,
      source_counts: sourceCounts,
      rss_signals: topArticles,
      recent_content,
      recent_content_text: recent_content.length
        ? recent_content.map((r, i) =>
            `${i + 1}. ${r.topic || r.hook || 'Untitled'} | ${r.source_url || 'No URL'} | CTA: ${r.cta || 'None'} | ${r.content_pillar || ''}`
          ).join('\n')
        : 'No recent content history available.',
      rss_signals_text: topArticles
        .map((r, index) => `${index + 1}. ${r.title}
Source: ${r.source}
Date: ${r.published_at || 'Unknown'}
URL: ${r.link}
Summary: ${r.summary}`)
        .join('\n\n')
    }
  }
];

const input = $input.first().json || {};

const raw =
  input.output?.[0]?.content?.find(c => c.type === 'output_text')?.text ||
  input.output?.[0]?.content?.[0]?.text ||
  input.text ||
  input.message ||
  '';

if (!raw) {
  throw new Error(
    'Missing Select Best Editorial Signal With OpenAI output. Found: ' +
    JSON.stringify(input).slice(0, 1500)
  );
}

let cleaned = String(raw)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    'Failed to parse Select Best Editorial Signal With OpenAI JSON. Raw output: ' +
    cleaned.slice(0, 1500)
  );
}

const requiredFields = [
  'signal_headline',
  'signal_source',
  'signal_date',
  'signal_url',
  'topic_tag',
  'signal_summary',
  'business_implication',
  'operational_pain',
  'company_angle',
  'artifact_type',
  'quality_score',
  'publish_decision',
  'cta',
  'post_heading',
  'content_mode',
  'content_pillar',
  'post_variant',
  'cta_strategy',
  'hook_style',
  'recommended_hashtags',
  'visual_format',
  'visual_eyebrow',
  'visual_headline',
  'visual_subheadline',
  'visual_footer'
];

for (const field of requiredFields) {
  if (parsed[field] === undefined || parsed[field] === null) {
    parsed[field] = '';
  }
}

if (!Array.isArray(parsed.bullet_points)) parsed.bullet_points = [];
if (!Array.isArray(parsed.recommended_hashtags)) parsed.recommended_hashtags = [];
if (!Array.isArray(parsed.visual_points)) parsed.visual_points = [];

parsed.quality_score = Number(parsed.quality_score || 0);
parsed.publish_decision = String(parsed.publish_decision || '').toLowerCase().trim();

if (!['publish', 'skip'].includes(parsed.publish_decision)) {
  parsed.publish_decision = parsed.quality_score >= 8 ? 'publish' : 'skip';
}

// V6.2 EDITORIAL CATEGORY GUARD
// Security incidents are not Example Company's editorial lane.
// Judge the SOURCE signal, not the AI-generated operational reframing.
const sourceText = [
  parsed.signal_headline,
  parsed.signal_summary,
  parsed.topic_tag
].join(' ').toLowerCase();

const securityIncidentPatterns = [
  /\bhack(?:ed|ing|s)?\b/,
  /\bcyber(?:security|attack|crime)?\b/,
  /\bsecurity vulnerability\b/,
  /\bvulnerabilit(?:y|ies)\b/,
  /\bexploit(?:ed|s|ing)?\b/,
  /\bmalware\b/,
  /\bransomware\b/,
  /\bdata breach\b/,
  /\bcredential theft\b/,
  /\bprompt injection\b/,
  /\bjailbreak(?:ing)?\b/
];

const isSecurityIncident = securityIncidentPatterns.some(rx => rx.test(sourceText));

if (isSecurityIncident) {
  parsed.publish_decision = 'skip';
  parsed.editorial_block_reason = 'Security/cyber incident is outside the Example Company editorial lane.';
  parsed.quality_score = Math.min(Number(parsed.quality_score || 0), 5);
}

const VALID_VISUAL_FORMATS = ['checklist', 'strong_statement', 'before_after', 'process_breakdown', 'mini_framework', 'friction_snapshot'];

if (parsed.publish_decision === 'publish') {
  if (!parsed.signal_headline) throw new Error('Missing signal_headline.');
  if (!parsed.signal_url) throw new Error('Missing signal_url.');
  if (!parsed.business_implication) throw new Error('Missing business_implication.');
  if (!parsed.operational_pain) throw new Error('Missing operational_pain.');
  if (!parsed.company_angle) throw new Error('Missing company_angle.');
  if (!parsed.artifact_type) throw new Error('Missing artifact_type.');
  if (!parsed.post_heading) throw new Error('Missing post_heading.');
  if (parsed.bullet_points.length > 5) {
    throw new Error(`bullet_points must contain 0 to 5 items. Received ${parsed.bullet_points.length}.`);
  }
  // AUDIT FIX (Check 5): validate each bullet_points entry has non-empty icon + text, not just
  // the array length. A missing field here would previously pass silently and only surface as
  // a thin/empty bullet line in the final post.
  parsed.bullet_points.forEach((bp, i) => {
    if (!bp || typeof bp !== 'object' || !String(bp.icon || '').trim() || !String(bp.text || '').trim()) {
      throw new Error(`bullet_points[${i}] is missing a non-empty icon or text field.`);
    }
  });
  if (!VALID_VISUAL_FORMATS.includes(parsed.visual_format)) {
    throw new Error(`Invalid visual_format "${parsed.visual_format}". Must be one of ${VALID_VISUAL_FORMATS.join(', ')}.`);
  }
  if (!parsed.visual_headline) throw new Error('Missing visual_headline.');
  if (parsed.visual_points.length < 3 || parsed.visual_points.length > 5) {
    throw new Error(`visual_points must contain 3 to 5 items. Received ${parsed.visual_points.length}.`);
  }
  // AUDIT FIX (Check 5): same per-item validation for visual_points (icon + title + description).
  parsed.visual_points.forEach((vp, i) => {
    if (!vp || typeof vp !== 'object' || !String(vp.icon || '').trim() || !String(vp.title || '').trim() || !String(vp.description || '').trim()) {
      throw new Error(`visual_points[${i}] is missing a non-empty icon, title, or description field.`);
    }
  });
  parsed.recommended_hashtags = parsed.recommended_hashtags.slice(0, 3);
}


// Deterministic editorial metadata comes from the cadence gate, not the model.
let plan = {};
let recent = [];
try {
  const prepared = $('Prepare RSS Signals').first().json || {};
  plan = prepared;
  recent = Array.isArray(prepared.recent_content) ? prepared.recent_content : [];
} catch {}

parsed.content_mode = plan.content_mode || parsed.content_mode || 'current_signal';
parsed.content_pillar = plan.content_pillar || parsed.content_pillar || 'Thought Leadership';
parsed.post_variant = plan.post_variant || parsed.post_variant || 'Opinion-Led';
parsed.cta_strategy = plan.cta_strategy || parsed.cta_strategy || 'question';
parsed.run_date_uk = plan.run_date_uk || '';
parsed.run_weekday_uk = plan.run_weekday_uk || '';
parsed.test_mode = plan.test_mode === true;
parsed.run_status = plan.run_status || (parsed.test_mode ? 'TEST_PREVIEW' : 'PRODUCTION');
parsed.execution_mode = plan.execution_mode || '';

if (parsed.publish_decision === 'publish') {
  const selectedUrl = String(parsed.signal_url || '').trim().toLowerCase();
  const duplicateUrl = recent.some(r =>
    selectedUrl && String(r.source_url || '').trim().toLowerCase() === selectedUrl
  );

  const words = (s) => new Set(
    String(s || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ')
      .split(/\s+/).filter(w => w.length > 3)
  );
  const similarity = (a, b) => {
    const A = words(a), B = words(b);
    if (!A.size || !B.size) return 0;
    const overlap = [...A].filter(x => B.has(x)).length;
    return overlap / Math.min(A.size, B.size);
  };

  const nearDuplicateTopic = recent.some(r =>
    similarity(parsed.signal_headline, r.topic || r.hook) >= 0.75
  );

  if (duplicateUrl || nearDuplicateTopic) {
    parsed.publish_decision = 'skip';
    parsed.quality_score = Math.min(parsed.quality_score, 7);
    parsed.skip_reason = duplicateUrl
      ? 'Duplicate source URL found in recent content history.'
      : 'Topic is too similar to recent content history.';
  }
}

return [
  {
    json: {
      ...parsed,
      run_id: `community-linkedin-${new Date().toISOString()}`,
      created_at: new Date().toISOString()
    }
  }
];

const source = $input.first().json;

return [
  {
    json: {
      ...source,
      run_id: source.run_id || `community-linkedin-${new Date().toISOString()}`,
      created_at: source.created_at || new Date().toISOString()
    }
  }
];

