const refinerOutput = $input.first().json;
const source = $('Normalise Editorial Brief').first().json;

const refined =
  refinerOutput.output?.[0]?.content?.find(c => c.type === 'output_text')?.text ||
  refinerOutput.output?.[0]?.content?.[0]?.text ||
  refinerOutput.text ||
  '';

if (!refined) {
  throw new Error(
    'No refined post text found. Refiner output: ' +
    JSON.stringify(refinerOutput).slice(0, 1500)
  );
}

const banned = [
  'game changer',
  'revolutionise',
  'revolutionize',
  'leverage',
  'leveraging',
  'unlock',
  'transformative',
  'revolutionary',
  'cutting edge',
  'seamless',
  'powerful',
  'this advancement',
  'this update helps',
  'operational efficiency',
  'synergy',
  'paradigm',
  'cutting-edge'
];

let cleaned = refined.trim();

for (const phrase of banned) {
  cleaned = cleaned.replace(new RegExp(phrase, 'gi'), '');
}

cleaned = cleaned
  .replace(/\n{3,}/g, '\n\n')
  .replace(/[ \t]{2,}/g, ' ')
  .trim();

if (cleaned.includes('undefined')) {
  throw new Error('BLOCKED: refined post contains undefined.');
}

if (cleaned.length < 80) {
  throw new Error('BLOCKED: refined post is too short.');
}

// AUDIT FIX (Check 5): the only length check previously was a character-count floor, which does
// not validate the intended 110-180 word target at all. This adds an actual word count and hard
// outer bounds (well outside the target range) that catch clearly broken output — truncated,
// runaway, or near-empty — without over-blocking normal LLM stylistic variance around the target.
const wordCount = cleaned.split(/\s+/).filter(Boolean).length;

if (wordCount < 70) {
  throw new Error(`BLOCKED: refined post is only ${wordCount} words, below the safe production range.`);
}

if (wordCount > 190) {
  throw new Error(`BLOCKED: refined post is ${wordCount} words, above the safe production range.`);
}

return [
  {
    json: {
      ...source,
      post_text: cleaned,
      refined_post: cleaned,
      original_post_text: source.post_text,
      status: source.status || 'Approved',
      error_log: source.error_log || '',
      word_count: wordCount
    }
  }
];

// V6.1 HASHTAG + FINAL LINKEDIN TEXT ASSEMBLY
const raw = Array.isArray($json.recommended_hashtags)
  ? $json.recommended_hashtags
  : [];

const normalise = (h) => String(h || '')
  .trim()
  .replace(/^#+/, '')
  .replace(/\s+/g, '');

let tags = [...new Set(raw.map(normalise).filter(Boolean))];

// Provide restrained fallbacks only when the editor returned too few.
// We keep the final total at 2-3, not a hashtag wall.
const modeFallbacks = {
  practical_playbook: ['OperationalAI', 'WorkflowAutomation', 'BusinessAutomation'],
  current_signal: ['AIOperations', 'OperationalAI', 'FutureOfWork'],
  practitioner_view: ['AIOperations', 'BusinessAutomation', 'OperationalAI'],
  operational_review: ['OperationalAI', 'WorkflowAutomation', 'AIAutomation']
};

const fallbacks = modeFallbacks[$json.content_mode] || ['OperationalAI', 'BusinessAutomation'];

for (const tag of fallbacks) {
  if (tags.length >= 2) break;
  if (!tags.includes(tag)) tags.push(tag);
}

tags = tags.slice(0, 3);

const hashtags = tags.map(h => `#${h}`).join(' ');
const basePost = String($json.post_text || '').trim();

if (!basePost) {
  throw new Error('Missing post_text before hashtag assembly.');
}

const linkedinPostText = hashtags
  ? `${basePost}\n\n${hashtags}`
  : basePost;

return [{
  json: {
    ...$json,
    hashtags,
    hashtag_count: tags.length,
    linkedin_post_text: linkedinPostText,
    post_text_with_hashtags: linkedinPostText
  }
}];

// V6.2 REATTACH FULL FINAL CONTENT CONTEXT
// IMPORTANT: use the Add Relevant Hashtags node as the canonical content source.
// Parse Final Post is earlier in the workflow and does not yet contain
// hashtags / linkedin_post_text.

const airtable = $input.first().json || {};

let content = {};
try {
  content = $('Add Relevant Hashtags').first().json || {};
} catch {
  content = $('Parse Final Post').first().json || {};
}

const fields = airtable.fields || {};

return [{
  json: {
    ...content,
    airtable_record_id: airtable.id || airtable.recordId || '',
    airtable_fields: fields,
    airtable_created_time: airtable.createdTime || ''
  }
}];

const cfg = $('Set Publishing Config').first().json || {};
const configured =
  cfg.screenshot_service_url &&
  cfg.screenshot_service_url !== 'YOUR_SCREENSHOT_SERVICE_URL';

return [{
  json: {
    ...$json,
    screenshot_service_available: !!configured,
    rendering_path: configured ? 'screenshot_service' : 'openai_fallback'
  }
}];

const items = $input.all();
const item = items[0];
const source = $('Build Editorial Card').first().json;

// Screenshot-service path returns raw PNG binary. OpenAI fallback path returns json.data[0].b64_json.
// Normalise both into the same shape (json.data[0].b64_json) so every downstream node can stay format-agnostic.

if (item.binary && item.binary.data) {
  const base64 = item.binary.data.data
    ? item.binary.data.data
    : Buffer.from(item.binary.data, 'base64').toString('base64');

  return [{
    json: {
      ...source,
      data: [{ b64_json: base64 }],
      render_method: 'screenshot_service'
    }
  }];
}

const j = item.json || {};

if (Array.isArray(j.data) && j.data[0]?.b64_json) {
  return [{
    json: {
      ...source,
      data: j.data,
      render_method: 'openai_fallback'
    }
  }];
}

throw new Error('BLOCKED: rendered image is missing both binary data and data[0].b64_json.');

