const qaInput = $input.first();
const response = qaInput.json || {};

// Recover the generated image and original content.
const imageContext = $('Normalize Rendered Image').first().json || {};

// Extract OpenAI Responses API text.
let responseText = '';

if (typeof response.output_text === 'string') {
  responseText = response.output_text;
}

if (!responseText && Array.isArray(response.output)) {
  for (const outputItem of response.output) {
    if (!Array.isArray(outputItem?.content)) continue;

    for (const contentItem of outputItem.content) {
      if (
        typeof contentItem?.text === 'string' &&
        ['output_text', 'text'].includes(contentItem.type)
      ) {
        responseText = contentItem.text;
        break;
      }
    }

    if (responseText) break;
  }
}

if (
  !responseText &&
  typeof response.choices?.[0]?.message?.content === 'string'
) {
  responseText = response.choices[0].message.content;
}

if (!responseText) {
  throw new Error(
    'BLOCKED: Image QA response did not contain readable output text.'
  );
}

const cleanedText = responseText
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let qa;

try {
  qa = JSON.parse(cleanedText);
} catch {
  throw new Error(
    `BLOCKED: Image QA returned invalid JSON. Raw output: ${cleanedText}`
  );
}

const score = Number(
  qa.visual_qa_score ??
  qa.score ??
  qa.qa_score ??
  0
);

const approved =
  qa.visual_qa_approved === true ||
  qa.approved === true ||
  String(
    qa.visual_qa_approved ??
    qa.approved ??
    ''
  ).toLowerCase() === 'true';

const issues = Array.isArray(
  qa.visual_qa_issues ?? qa.issues
)
  ? qa.visual_qa_issues ?? qa.issues
  : qa.visual_qa_issues || qa.issues
    ? [String(qa.visual_qa_issues || qa.issues)]
    : [];

const reason = String(
  qa.visual_qa_reason ??
  qa.reason ??
  ''
).trim();

return [
  {
    json: {
      ...imageContext,
      visual_qa_score: score,
      visual_qa_approved: approved,
      visual_qa_issues: issues,
      visual_qa_reason: reason,
      image_qa_raw_text: cleanedText
    },
    binary: imageContext.binary || qaInput.binary
  }
];

const inputItem = $input.first();
const data = inputItem.json || {};

const retryCount = Number(data.image_retry_count || 0) + 1;

if (retryCount > 2) {
  throw new Error(
    `BLOCKED: image failed QA after ${retryCount} attempts. ` +
    `Score=${data.visual_qa_score || 0}. ` +
    `Issues=${data.visual_qa_issues || ''}. ` +
    `Reason=${data.visual_qa_reason || ''}`
  );
}

return [
  {
    json: {
      ...data,
      image_qa_passed: false,
      image_qa_failed: true,
      image_retry_count: retryCount,
      visual_qa_score: Number(data.visual_qa_score || 0),
      visual_qa_issues: data.visual_qa_issues || '',
      visual_qa_reason: data.visual_qa_reason || '',
      image_failure_reason:
        `Image QA failed. Attempt=${retryCount}. ` +
        `Score=${data.visual_qa_score || 0}. ` +
        `Issues=${data.visual_qa_issues || ''}. ` +
        `Reason=${data.visual_qa_reason || ''}`,
      use_fallback_image: true
    },
    binary: inputItem.binary || {}
  }
];

