const registrationInput = $input.first();
const registration = registrationInput.json || {};

// Original post content
let content = {};

try {
  content = $('Restore Editorial Context').first().json || {};
} catch {
  try {
    content = $('Build Test Preview').first().json || {};
  } catch {
    content = {};
  }
}

let postText = String(
  content.post_text ||
  content.linkedin_post ||
  content.final_post ||
  content.post_copy ||
  content.refined_post ||
  ''
).trim();

if (!postText) {
  throw new Error('BLOCKED: post_text is missing.');
}

if (postText.toLowerCase().includes('undefined')) {
  throw new Error('BLOCKED: post_text contains undefined.');
}

// Clean formatting
postText = postText
  .replace(/—/g, ',')
  .replace(/–/g, ',')
  .replace(/\n{3,}/g, '\n\n')
  .replace(/[ \t]{2,}/g, ' ')
  .trim();

// Remove existing hashtags to prevent duplicates
postText = postText.replace(/#\w+/g, '').trim();

// Preferred Example Company hashtags
const hashtags = String(
  content.hashtags ||
  '#OperationalAI #WorkflowAutomation #AIImplementation'
).trim();

const finalPostText = `${postText}

${hashtags}`.trim();

// LinkedIn registration response
const value = registration.value || {};

const asset =
  value.asset ||
  registration.asset ||
  '';

const uploadMechanism =
  value.uploadMechanism ||
  registration.uploadMechanism ||
  {};

let uploadUrl = '';

// LinkedIn uses a dynamically named upload-mechanism property.
for (const mechanism of Object.values(uploadMechanism)) {
  if (
    mechanism &&
    typeof mechanism === 'object' &&
    typeof mechanism.uploadUrl === 'string'
  ) {
    uploadUrl = mechanism.uploadUrl;
    break;
  }
}

// Fallback recursive search
if (!uploadUrl) {
  const findUploadUrl = (object) => {
    if (!object || typeof object !== 'object') return '';

    if (typeof object.uploadUrl === 'string') {
      return object.uploadUrl;
    }

    for (const value of Object.values(object)) {
      const found = findUploadUrl(value);
      if (found) return found;
    }

    return '';
  };

  uploadUrl = findUploadUrl(registration);
}

if (!asset) {
  throw new Error('BLOCKED: LinkedIn image asset URN is missing.');
}

if (!uploadUrl) {
  throw new Error('BLOCKED: LinkedIn uploadUrl is missing.');
}

// Recover the PNG binary created earlier
let binary = {};

try {
  binary = $('Convert to File').first().binary || {};
} catch {
  binary = registrationInput.binary || {};
}

if (!binary.data) {
  throw new Error('BLOCKED: LinkedIn image binary is missing.');
}

return [
  {
    json: {
      ...content,

      post_text: finalPostText,
      refined_post: finalPostText,

      asset,
      uploadUrl,
      linkedin_registration: registration,
      image_available: true,

      signal_headline: content.signal_headline || 'Example Company AI Brief',
      airtable_record_id: content.airtable_record_id,
      run_id: content.run_id,
      source_url: content.signal_url || content.source_url || ''
    },
    binary
  }
];

// V6.5 ONE-POST GUARD
// Never allow more than one post payload to reach LinkedIn in a single execution.
const inputItems = $input.all();

if (inputItems.length !== 1) {
  throw new Error(`BLOCKED: ${inputItems.length} items reached publish. Expected exactly 1.`);
}

const source = $('Prepare LinkedIn Asset').first().json;
const text = String(source.post_text || '').trim();
const asset = String(source.asset || '').trim();

if (!text || text.includes('undefined')) {
  throw new Error('BLOCKED: post_text missing or contains undefined.');
}

if (text.toUpperCase() === 'SKIP') {
  throw new Error('BLOCKED: post_text is SKIP.');
}

if (!asset || !asset.startsWith('urn:li:digitalmediaAsset:')) {
  throw new Error('BLOCKED: LinkedIn asset missing.');
}

const validModes = ['practical_playbook','current_signal','practitioner_view','operational_review'];
if (!validModes.includes(source.content_mode)) {
  throw new Error(`BLOCKED: invalid or missing content_mode: ${source.content_mode || 'missing'}`);
}

// This workflow has one scheduled execution and one item path.
// Combined with the cadence gate this prevents same-run/multi-item posting.
return [{ json: { ...source, publish_guard_passed: true } }];

