function safeNodeJson(nodeName) {
  try {
    return $(nodeName).first().json || {};
  } catch (error) {
    return {};
  }
}

const post = $input.first().json || {};

const finalGuard = safeNodeJson('Enforce One Post Per Run');
const linkedInAsset = safeNodeJson('Prepare LinkedIn Asset');
const contentContext = safeNodeJson('Restore Editorial Context');
const airtableCreate = safeNodeJson('Create Airtable Editorial Record');

const urn =
  post.id ||
  post.urn ||
  post.value?.id ||
  post.headers?.['x-linkedin-id'] ||
  finalGuard.LinkedIn_URN ||
  linkedInAsset.LinkedIn_URN ||
  '';

const runId =
  finalGuard.run_id ||
  linkedInAsset.run_id ||
  contentContext.run_id ||
  airtableCreate.fields?.Run_ID ||
  airtableCreate.fields?.id ||
  '';

const possibleRecordIds = [
  finalGuard.airtable_record_id,
  linkedInAsset.airtable_record_id,
  contentContext.airtable_record_id,
  airtableCreate.id,
  airtableCreate.recordId,
  airtableCreate.records?.[0]?.id
].filter(Boolean);

const airtableRecordId = possibleRecordIds.find(id =>
  typeof id === 'string' && id.startsWith('rec')
) || '';

const postText =
  finalGuard.linkedin_post_text ||
  finalGuard.post_text_with_hashtags ||
  linkedInAsset.linkedin_post_text ||
  linkedInAsset.post_text_with_hashtags ||
  contentContext.linkedin_post_text ||
  contentContext.post_text_with_hashtags ||
  finalGuard.post_text ||
  linkedInAsset.post_text ||
  contentContext.post_text ||
  contentContext.refined_post ||
  '';

if (!runId) {
  throw new Error('Missing run_id. Cannot find Airtable row.');
}

if (!postText || postText.includes('undefined')) {
  throw new Error('Missing or invalid post text for Airtable update.');
}

return [
  {
    json: {
      run_id: runId,
      airtable_record_id: airtableRecordId,
      Status: urn ? 'Posted' : 'Failed_Post',
      Post_URL: urn ? `https://www.linkedin.com/feed/update/${urn}/` : '',
      Error_Log: urn ? '' : 'LinkedIn post completed but no URN returned',
      LinkedIn_URN: urn,
      Image_URL: '',
      Post_Text: postText,
      signal_headline: finalGuard.signal_headline || linkedInAsset.signal_headline || contentContext.signal_headline || '',
      source_url: finalGuard.signal_url || linkedInAsset.signal_url || contentContext.signal_url || ''
    }
  }
];

const input = $input.first().json || {};

// Supports both Airtable node output and HTTP Airtable create/update output
const record =
  input.records?.[0] ||
  input;

const fields =
  record.fields ||
  input.fields ||
  {};

const fallback = (() => {
  try {
    return $('Prepare Publishing Audit').first().json || {};
  } catch {
    return {};
  }
})();

const today = new Date().toLocaleDateString('en-GB', {
  day: 'numeric',
  month: 'long',
  year: 'numeric'
});

const status =
  fields.Status ||
  fallback.Status ||
  'Posted';

const headline =
  fields.Topic ||
  fallback.signal_headline ||
  fallback.Topic ||
  '';

const urn =
  fields.LinkedIn_URN ||
  fallback.LinkedIn_URN ||
  '';

const postUrl =
  fields.Post_URL ||
  fallback.Post_URL ||
  '';

const postText =
  fields.Draft_Copy ||
  fields.Message ||
  fallback.Post_Text ||
  fallback.linkedin_post_text ||
  fallback.post_text_with_hashtags ||
  fallback.post_text ||
  '';

const source =
  fields.Source_URL ||
  fallback.source_url ||
  fallback.signal_url ||
  '';

const errorLog =
  fields.Error_Log ||
  fallback.Error_Log ||
  '';

return [
  {
    json: {
      subject: `Example Company LinkedIn Publish Log | ${today}`,
      html: `
        <p><strong>Status:</strong> ${status}</p>
        <p><strong>Headline:</strong> ${headline}</p>
        <p><strong>URN:</strong> ${urn}</p>
        <p><strong>Post URL:</strong> ${postUrl}</p>
        ${errorLog ? `<p><strong>Error:</strong> ${errorLog}</p>` : ''}
        <p><strong>Post:</strong></p>
        <p>${String(postText || '').replace(/\n/g, '<br>')}</p>
        <p><strong>Source:</strong> ${source}</p>
      `,
      message: `
        Status: ${status}

        Headline: ${headline}

        URN: ${urn}

        Post URL: ${postUrl}

        Post:
        ${postText}

        Source: ${source}
      `
    }
  }
];

// V6.1 SAFE TEST PREVIEW
// This node is reached BEFORE Convert to File, LinkedIn upload/publish and Airtable publishing updates.
const j = $input.first().json || {};

// Defensive recovery: if a downstream renderer unexpectedly dropped
// final-copy fields, recover them from the canonical Add Relevant Hashtags node.
let canonical = {};
try {
  canonical = $('Add Relevant Hashtags').first().json || {};
} catch {}

const merged = { ...canonical, ...j };

const finalText =
  merged.linkedin_post_text ||
  merged.post_text_with_hashtags ||
  (merged.hashtags ? `${String(merged.post_text || '').trim()}\n\n${merged.hashtags}` : merged.post_text) ||
  '';

const today = new Date().toLocaleDateString('en-GB', {
  timeZone: 'Europe/London',
  day: 'numeric',
  month: 'long',
  year: 'numeric'
});

const esc = (s) => String(s || '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

return [{
  json: {
    test_status: 'TEST_PREVIEW',
    status: 'TEST_PREVIEW',
    publishing_blocked: true,
    airtable_write_blocked: true,
    post_text: merged.post_text || '',
    hashtags: merged.hashtags || '',
    linkedin_post_text: finalText,
    source_url: merged.signal_url || '',
    signal_headline: merged.signal_headline || '',
    content_mode: merged.content_mode || '',
    visual_format: merged.resolved_visual_format || merged.visual_format || '',
    visual_qa_score: merged.visual_qa_score ?? 0,
    visual_qa_approved: merged.visual_qa_approved === true,
    rendering_path: merged.render_method || '',
    subject: `TEST PREVIEW | Example Company LinkedIn | ${today}`,
    html: `
      <p><strong>Status:</strong> TEST_PREVIEW</p>
      <p><strong>Safety:</strong> LinkedIn publishing and Airtable publishing updates were blocked.</p>
      <p><strong>Mode:</strong> ${esc(merged.content_mode || '')}</p>
      <p><strong>Headline:</strong> ${esc(merged.signal_headline || '')}</p>
      <p><strong>Add Relevant Hashtagss:</strong> ${esc(merged.hashtags || '')}</p>
      <p><strong>Visual QA:</strong> ${esc(merged.visual_qa_score ?? '')} | approved: ${merged.visual_qa_approved === true ? 'yes' : 'no'}</p>
      <p><strong>Final LinkedIn preview:</strong></p>
      <p>${esc(finalText).replace(/\n/g, '<br>')}</p>
      <p><strong>Source:</strong> ${esc(merged.signal_url || '')}</p>
    `,
    message: `Status: TEST_PREVIEW

LinkedIn publishing: BLOCKED
Airtable publishing update: BLOCKED

Mode: ${merged.content_mode || ''}
Headline: ${merged.signal_headline || ''}
Add Relevant Hashtagss: ${merged.hashtags || ''}

Final LinkedIn preview:
${finalText}

Source: ${merged.signal_url || ''}`
  }
}];

// COMMUNITY SAFE CADENCE GATE
// Scheduled executions can publish on configured posting days.
// Manual/test executions ALWAYS run in TEST_PREVIEW and are blocked before LinkedIn publishing.

const cfg = $('Set Publishing Config').first().json || {};
const now = new Date();

let executionMode = '';
try {
  executionMode = String($execution?.mode || '');
} catch {}

const isManualTest = executionMode === 'test';
const timezone = String(cfg.timezone || 'Europe/London');

const parts = new Intl.DateTimeFormat('en-GB', {
  timeZone: timezone,
  weekday: 'long',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).formatToParts(now);

const get = type => parts.find(p => p.type === type)?.value || '';
const weekday = get('weekday');
const localDate = `${get('year')}-${get('month')}-${get('day')}`;

const allowedDays = String(cfg.posting_days || 'Monday,Wednesday,Thursday,Sunday')
  .split(',')
  .map(v => v.trim())
  .filter(Boolean);

const plans = {
  Monday: {
    content_mode: 'practical_playbook',
    content_pillar: 'Education',
    post_variant: 'Educational',
    cta_strategy: 'save_or_follow',
    editorial_job: 'Teach one practical method, checklist or diagnostic the reader can use.'
  },
  Wednesday: {
    content_mode: 'current_signal',
    content_pillar: 'Thought Leadership',
    post_variant: 'Opinion-Led',
    cta_strategy: 'question',
    editorial_job: 'Translate one current AI development into a concrete operating implication.'
  },
  Thursday: {
    content_mode: 'practitioner_view',
    content_pillar: 'Opinion',
    post_variant: 'Opinion-Led',
    cta_strategy: 'soft_or_none',
    editorial_job: 'Write from a practitioner point of view: what an operator would actually change in the workflow.'
  },
  Sunday: {
    content_mode: 'operational_review',
    content_pillar: 'Automation',
    post_variant: 'Educational',
    cta_strategy: 'commercial_once',
    editorial_job: 'Use a structured operational review format with a clear diagnostic or practical takeaway.'
  }
};

let todayPlan = plans[weekday];

if (isManualTest && !todayPlan) {
  todayPlan = {
    content_mode: 'current_signal',
    content_pillar: 'Thought Leadership',
    post_variant: 'Opinion-Led',
    cta_strategy: 'question',
    editorial_job: 'TEST PREVIEW: translate one current AI development into a concrete operating implication.'
  };
}

if (!isManualTest && !allowedDays.includes(weekday)) {
  return [];
}

if (!todayPlan) {
  return [];
}

return [{
  json: {
    ...cfg,
    run_date_local: localDate,
    run_weekday_local: weekday,
    execution_mode: executionMode || 'unknown',
    test_mode: isManualTest,
    run_status: isManualTest ? 'TEST_PREVIEW' : 'PRODUCTION',
    cadence_reason: isManualTest
      ? 'Manual/test execution: preview allowed, publishing blocked.'
      : `Scheduled ${weekday} editorial slot.`,
    max_posts_today: Number(cfg.max_posts_per_day || 1),
    ...todayPlan
  }
}];
